import { mkdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import {
  createRunSchema, reproductionSchema, reproStepSchema,
  type ActionRecord, type Candidate, type CartCheckpoint, type CartItem,
  type CreateRun, type Reproduction, type ShopState,
} from '@bugreplay/contracts';

export const ASSERTION_MARKER = 'BUGREPLAY_CART_PRESERVATION';

function normalizedCart(cart: CartItem[]): CartItem[] {
  if (!Array.isArray(cart)) throw new Error('Invalid trusted cart state');
  const ids = new Set<string>();
  return cart.map(({ productId, quantity }) => {
    if (typeof productId !== 'string' || !productId.trim() || ids.has(productId) || !Number.isSafeInteger(quantity) || quantity < 1) {
      throw new Error('Invalid or duplicate cart item in trusted state');
    }
    ids.add(productId);
    return { productId, quantity };
  }).sort((a, b) => a.productId.localeCompare(b.productId));
}

function validateState(state: ShopState): void {
  normalizedCart(state.cart);
  if (typeof state.address !== 'string' || !Number.isSafeInteger(state.saveSeq) || state.saveSeq < 0 || typeof state.saved !== 'boolean' || typeof state.busy !== 'boolean') {
    throw new Error('Invalid trusted checkout state');
  }
}

function sameState(a: ShopState, b: ShopState): boolean {
  return JSON.stringify(normalizedCart(a.cart)) === JSON.stringify(normalizedCart(b.cart)) &&
    a.address === b.address && a.saveSeq === b.saveSeq && a.saved === b.saved && a.busy === b.busy;
}

/** Select trusted records only; the model cannot provide code or reproduction steps. */
export function compileCandidate(input: CreateRun, records: ActionRecord[], checkpoints: CartCheckpoint[], candidate: Candidate): Reproduction {
  createRunSchema.parse(input);
  const episode = records.filter((record) => record.episodeId === candidate.episodeId);
  if (!episode.length || episode[0].step.kind !== 'goto' || episode[0].semantic !== 'navigation') {
    throw new Error('Candidate has no complete clean-episode navigation prefix');
  }
  const ids = new Set<string>();
  for (const record of episode) {
    reproStepSchema.parse(record.step);
    if (ids.has(record.step.id)) throw new Error('Duplicate trusted step ID');
    ids.add(record.step.id);
    validateState(record.after);
    if (record.before) validateState(record.before);
    if (record.step.kind === 'goto') {
      const destination = new URL(record.step.path, input.targetUrl);
      if (destination.origin !== new URL(input.targetUrl).origin || record.step.path.includes('\\')) {
        throw new Error('Recorded navigation escapes the target origin');
      }
    }
  }
  const matching = checkpoints.filter((checkpoint) => checkpoint.id === candidate.checkpointId && checkpoint.episodeId === candidate.episodeId);
  if (matching.length !== 1) throw new Error('Candidate must select one trusted checkpoint in its episode');
  const checkpoint = matching[0];
  validateState(checkpoint.state);
  const captureIndex = episode.findIndex((record) => record.step.id === checkpoint.afterStepId);
  const endIndex = episode.findIndex((record) => record.step.id === candidate.endStepId);
  if (captureIndex < 0 || endIndex <= captureIndex) throw new Error('Candidate end must follow its checkpoint');
  if (!checkpoint.state.cart.length || checkpoint.state.busy || !sameState(checkpoint.state, episode[captureIndex].after)) {
    throw new Error('Checkpoint must contain the completed nonempty trusted cart');
  }
  const operations = episode.slice(captureIndex + 1, endIndex + 1);
  const permitted = new Set(['navigation', 'checkout-edit', 'checkout-save']);
  if (operations.some((record) => !permitted.has(record.semantic))) {
    throw new Error('Candidate contains a prohibited or unknown action after its cart checkpoint');
  }
  const final = episode[endIndex];
  if (final.semantic !== 'checkout-save' || final.step.kind !== 'click' || !final.before ||
      final.after.busy || !final.after.saved || final.after.saveSeq <= checkpoint.state.saveSeq ||
      final.after.saveSeq <= final.before.saveSeq || final.after.address.trim() === checkpoint.state.address.trim() ||
      final.after.address.trim() === final.before.address.trim() || !final.after.address.trim()) {
    throw new Error('Candidate must end with a completed new save of a changed address');
  }
  return reproductionSchema.parse({
    version: 1, complaint: input.complaint, expected: input.expected, observed: candidate.observed,
    steps: episode.slice(0, endIndex + 1).map((record) => record.step),
    oracle: { kind: input.oracleKind, captureAfterStepId: checkpoint.afterStepId, compareAfterStepId: final.step.id },
  });
}

/** This source is generated by ordinary code, never by the investigating model. */
export function reproductionSource(reproduction: Reproduction): string {
  reproductionSchema.parse(reproduction);
  const data = JSON.stringify(reproduction, null, 2);
  return `import { test, expect, type Page, type Locator } from '@playwright/test';

const reproduction = ${data} as const;
const fs = process.getBuiltinModule('node:fs');
const evidencePath = process.env.BUGREPLAY_EVIDENCE_PATH;
const evidence: Record<string, any> = { version: 1, nonce: process.env.BUGREPLAY_ATTEMPT_NONCE, stage: 'starting', assertionReached: false, contextClosed: false };
function saveEvidence() {
  if (evidencePath) fs.writeFileSync(evidencePath, JSON.stringify(evidence, null, 2));
}
function stage(value: string) { evidence.stage = value; saveEvidence(); }
function target(page: Page, spec: { role: any; name: string; exact: true; scope?: { role: any; name: string } }): Locator {
  const scope = spec.scope ? page.getByRole(spec.scope.role, { name: spec.scope.name, exact: true }) : page;
  return scope.getByRole(spec.role, { name: spec.name, exact: true });
}
async function readState(page: Page) {
  const cart = page.getByRole('region', { name: 'Cart', exact: true });
  if (await cart.count() !== 1 || !await cart.isVisible()) throw new Error('Setup: expected one visible Cart region');
  const busy = await cart.getAttribute('aria-busy');
  if (busy !== 'false' && busy !== 'true') throw new Error('Setup: Cart aria-busy is missing');
  const rows = cart.locator('[data-product-id]');
  const items: Array<{ productId: string; quantity: number }> = [];
  const seen = new Set<string>();
  for (const row of await rows.all()) {
    if (!await row.isVisible()) continue;
    const productId = await row.getAttribute('data-product-id');
    const rawQuantity = await row.getAttribute('data-quantity');
    const quantity = Number(rawQuantity);
    if (!productId || seen.has(productId) || !rawQuantity || !/^\\d+$/.test(rawQuantity) || !Number.isSafeInteger(quantity) || quantity < 1) throw new Error('Setup: invalid visible cart row');
    seen.add(productId); items.push({ productId, quantity });
  }
  const addresses = page.locator('[data-checkout-address]:visible');
  const statuses = page.locator('[role="status"][data-save-seq]:visible');
  if (await addresses.count() !== 1 || await statuses.count() !== 1) throw new Error('Setup: missing or ambiguous visible checkout state');
  const address = (await addresses.innerText()).trim();
  const status = (await statuses.innerText()).trim();
  const rawSequence = await statuses.getAttribute('data-save-seq');
  const saveSeq = Number(rawSequence);
  if (!rawSequence || !/^\\d+$/.test(rawSequence) || !Number.isSafeInteger(saveSeq)) throw new Error('Setup: invalid completed-save sequence');
  return { cart: items.sort((a, b) => a.productId.localeCompare(b.productId)), address, saveSeq, saved: status === 'Address saved', busy: busy === 'true' };
}
async function stableState(page: Page, predicate: (state: Awaited<ReturnType<typeof readState>>) => boolean = () => true) {
  const until = Date.now() + 5000;
  let previous = '';
  let stableSince = 0;
  while (Date.now() < until) {
    const value = await readState(page);
    const serialized = JSON.stringify(value);
    if (!value.busy && predicate(value)) {
      if (serialized !== previous) { previous = serialized; stableSince = Date.now(); }
      if (Date.now() - stableSince >= 250) return value;
    } else { previous = ''; stableSince = 0; }
    await page.waitForTimeout(50);
  }
  throw new Error('Setup: UI did not reach a stable completed state with a new changed-address save');
}

test('cart survives a completed checkout address change', async ({ browser }, testInfo) => {
  test.setTimeout(Number(process.env.BUGREPLAY_TEST_TIMEOUT_MS || 55000));
  const base = new URL(process.env.BASE_URL || 'http://localhost:4173');
  const context = await browser.newContext({ recordVideo: { dir: testInfo.outputPath('video'), size: { width: 1280, height: 720 } }, viewport: { width: 1280, height: 720 } });
  const page = await context.newPage();
  page.setDefaultTimeout(5000);
  page.setDefaultNavigationTimeout(10000);
  let initial: Awaited<ReturnType<typeof readState>> | undefined;
  let beforeFinal: Awaited<ReturnType<typeof readState>> | undefined;
  let operationState: Awaited<ReturnType<typeof readState>> | undefined;
  let thrown: unknown;
  try {
    stage('setup');
    for (const step of reproduction.steps) {
      evidence.stepId = step.id; saveEvidence();
      if (step.id === reproduction.oracle.compareAfterStepId) {
        beforeFinal = await stableState(page);
        evidence.beforeSaveState = beforeFinal; saveEvidence();
      }
      if (step.kind === 'goto') {
        const destination = new URL(step.path, base);
        if (destination.origin !== base.origin) throw new Error('Setup: navigation escapes BASE_URL origin');
        await page.goto(destination.href, { waitUntil: 'domcontentloaded' });
      } else {
        const locator = target(page, step.locator);
        await locator.waitFor({ state: 'visible', timeout: 5000 });
        if (await locator.count() !== 1) throw new Error('Setup: locator is missing or ambiguous');
        const semantic = await locator.evaluate((element) => element.closest('[data-action]')?.getAttribute('data-action') ?? 'unknown');
        if (initial && !['navigation', 'checkout-edit', 'checkout-save'].includes(semantic)) throw new Error('Setup: prohibited action after checkpoint');
        if (step.id === reproduction.oracle.compareAfterStepId && semantic !== 'checkout-save') throw new Error('Setup: final action is not a checkout save');
        if (step.kind === 'click') await locator.click();
        else if (step.kind === 'fill') await locator.fill(step.value);
        else if (step.kind === 'select') await locator.selectOption(step.value);
        else if (step.kind === 'check') await locator.setChecked(step.checked);
      }
      if (step.id === reproduction.oracle.captureAfterStepId) {
        initial = await stableState(page);
        if (!initial.cart.length) throw new Error('Setup: cart checkpoint is empty');
        evidence.initialCart = initial.cart; evidence.initialState = initial;
        evidence.beforeScreenshot = testInfo.outputPath('before.png');
        await page.screenshot({ path: evidence.beforeScreenshot, fullPage: true });
        stage('checkpoint_captured');
      }
      if (step.id === reproduction.oracle.compareAfterStepId) {
        if (!initial || !beforeFinal) throw new Error('Setup: missing initial checkpoint');
        stage('waiting_for_changed_address_save');
        operationState = await stableState(page, (value) => value.saved && value.saveSeq > initial!.saveSeq && value.saveSeq > beforeFinal!.saveSeq && value.address.length > 0 && value.address !== initial!.address && value.address !== beforeFinal!.address);
      }
    }
    if (!initial || !operationState) throw new Error('Setup: incomplete reproduction');
    evidence.actualCart = operationState.cart; evidence.actualState = operationState;
    evidence.afterScreenshot = testInfo.outputPath('after.png');
    await page.screenshot({ path: evidence.afterScreenshot, fullPage: true });
    evidence.assertionReached = true;
    stage('cart_assertion');
    expect(operationState.cart, '${ASSERTION_MARKER}').toEqual(initial.cart);
    stage('passed');
  } catch (error) {
    thrown = error;
    evidence.error = error instanceof Error ? error.message : String(error);
    evidence.errorType = evidence.stage === 'cart_assertion' && evidence.error.includes('${ASSERTION_MARKER}') ? 'cart_assertion_failed' : 'automation_or_setup_error';
    stage(evidence.errorType === 'cart_assertion_failed' ? 'cart_assertion_failed' : 'inconclusive');
  } finally {
    try {
      await context.close();
      evidence.contextClosed = true;
      evidence.videoPath = await page.video()?.path();
    } catch (error) {
      evidence.cleanupError = error instanceof Error ? error.message : String(error);
      evidence.stage = 'inconclusive'; evidence.errorType = 'cleanup_error';
      thrown = error;
    }
    saveEvidence();
    await testInfo.attach('verification-evidence', { body: JSON.stringify(evidence, null, 2), contentType: 'application/json' });
  }
  if (thrown) throw thrown;
});
`;
}

export async function writeReproduction(dir: string, reproduction: Reproduction): Promise<void> {
  const parsed = reproductionSchema.parse(reproduction);
  await mkdir(dir, { recursive: true });
  await writeFile(path.join(dir, 'reproduction.json'), JSON.stringify(parsed, null, 2) + '\n');
  await writeFile(path.join(dir, 'repro.spec.ts'), reproductionSource(parsed));
}
import { spawn } from 'node:child_process';
import { randomUUID } from 'node:crypto';
import { copyFile, mkdir, readFile, writeFile } from 'node:fs/promises';
import { createRequire } from 'node:module';
import path from 'node:path';
import type { CartItem, VerificationAttempt, VerificationResult } from '@bugreplay/contracts';
import { ASSERTION_MARKER } from './compiler.js';

export interface VerifyOptions {
  dir: string;
  baseUrl: string;
  attempts?: number;
  /** Total wall-clock limit across all independent processes. */
  timeoutMs?: number;
  signal?: AbortSignal;
}

const require = createRequire(import.meta.url);
const playwrightCli = require.resolve('@playwright/test/cli');

function isolatedEnvironment(extra: Record<string, string>): NodeJS.ProcessEnv {
  const env: NodeJS.ProcessEnv = {};
  for (const name of ['PATH', 'HOME', 'TMPDIR', 'TMP', 'TEMP', 'SystemRoot', 'USERPROFILE', 'XDG_CACHE_HOME', 'PLAYWRIGHT_BROWSERS_PATH']) {
    if (process.env[name] !== undefined) env[name] = process.env[name];
  }
  return { ...env, CI: '1', FORCE_COLOR: '0', ...extra };
}

async function execute(config: string, env: NodeJS.ProcessEnv, timeoutMs: number, signal?: AbortSignal): Promise<{ exitCode: number | null; stdout: string; stderr: string; interrupted?: string }> {
  return new Promise((resolve) => {
    const child = spawn(process.execPath, [playwrightCli, 'test', '--config', config, '--workers=1', '--retries=0'], {
      cwd: path.dirname(config), env, stdio: ['ignore', 'pipe', 'pipe'], detached: process.platform !== 'win32',
    });
    let stdout = '';
    let stderr = '';
    let interrupted: string | undefined;
    let killTimer: NodeJS.Timeout | undefined;
    const stop = (reason: string) => {
      if (interrupted) return;
      interrupted = reason;
      const kill = (kind: NodeJS.Signals) => {
        try {
          if (process.platform !== 'win32' && child.pid) process.kill(-child.pid, kind);
          else child.kill(kind);
        } catch { /* The process may already have closed. */ }
      };
      kill('SIGTERM');
      killTimer = setTimeout(() => kill('SIGKILL'), 1000);
      killTimer.unref();
    };
    const onAbort = () => stop('cancelled');
    const timer = setTimeout(() => stop('verification_timeout'), Math.max(1, timeoutMs));
    signal?.addEventListener('abort', onAbort, { once: true });
    if (signal?.aborted) stop('cancelled');
    child.stdout.on('data', (data: Buffer) => { stdout += data.toString(); });
    child.stderr.on('data', (data: Buffer) => { stderr += data.toString(); });
    child.on('error', (error) => { stderr += error.message; interrupted ??= 'process_error'; });
    child.on('close', (exitCode) => {
      clearTimeout(timer);
      if (killTimer) clearTimeout(killTimer);
      signal?.removeEventListener('abort', onAbort);
      resolve({ exitCode, stdout, stderr, interrupted });
    });
  });
}

async function readJson(file: string): Promise<any | undefined> {
  try { return JSON.parse(await readFile(file, 'utf8')); } catch { return undefined; }
}

function testsFrom(report: any): any[] {
  const tests: any[] = [];
  function walk(suite: any) {
    for (const spec of suite.specs ?? []) tests.push(...(spec.tests ?? []));
    for (const child of suite.suites ?? []) walk(child);
  }
  for (const suite of report?.suites ?? []) walk(suite);
  return tests;
}

function validCart(value: unknown): value is CartItem[] {
  if (!Array.isArray(value)) return false;
  const ids = new Set<string>();
  for (const item of value) {
    if (!item || typeof item.productId !== 'string' || !item.productId || ids.has(item.productId) || !Number.isSafeInteger(item.quantity) || item.quantity < 1) return false;
    ids.add(item.productId);
  }
  return true;
}

function classify(report: any, evidence: any, nonce: string, exitCode: number | null, interrupted?: string): Pick<VerificationAttempt, 'classification' | 'errorType' | 'error'> {
  if (interrupted) return { classification: 'inconclusive', errorType: interrupted, error: 'Independent Playwright process did not complete' };
  const tests = testsFrom(report);
  if (!report || (report.errors?.length ?? 0) !== 0 || tests.length !== 1 || tests[0].results?.length !== 1 || evidence?.nonce !== nonce || evidence?.contextClosed !== true) {
    return { classification: 'inconclusive', errorType: 'incomplete_verification', error: 'Missing clean completed execution, reporter result, or matching stage evidence' };
  }
  const result = tests[0].results[0];
  const errors = result.errors ?? (result.error ? [result.error] : []);
  const validOracle = evidence.assertionReached === true && validCart(evidence.initialCart) && evidence.initialCart.length > 0 && validCart(evidence.actualCart) &&
    evidence.initialState?.busy === false && evidence.actualState?.busy === false && evidence.actualState?.saved === true &&
    evidence.actualState.saveSeq > evidence.initialState.saveSeq && evidence.actualState.address !== evidence.initialState.address &&
    evidence.beforeSaveState?.busy === false && evidence.actualState.saveSeq > evidence.beforeSaveState.saveSeq &&
    evidence.actualState.address !== evidence.beforeSaveState.address;
  if (exitCode === 0 && tests[0].status === 'expected' && result.status === 'passed' && errors.length === 0 && evidence.stage === 'passed' && validOracle &&
      JSON.stringify(evidence.initialCart) === JSON.stringify(evidence.actualCart)) {
    return { classification: 'passed' };
  }
  if (exitCode === 1 && tests[0].status === 'unexpected' && result.status === 'failed' && errors.length === 1 &&
      typeof errors[0].message === 'string' && errors[0].message.includes(ASSERTION_MARKER) && validOracle &&
      evidence.stage === 'cart_assertion_failed' && evidence.errorType === 'cart_assertion_failed' &&
      JSON.stringify(evidence.initialCart) !== JSON.stringify(evidence.actualCart) && !evidence.cleanupError) {
    return { classification: 'matched_failure', errorType: ASSERTION_MARKER, error: errors[0].message };
  }
  return { classification: 'inconclusive', errorType: evidence.errorType ?? result.status ?? 'automation_or_setup_error', error: evidence.error ?? errors[0]?.message ?? 'The intended regression assertion did not produce a matching result' };
}

async function publishFile(source: unknown, attemptDir: string, destination: string): Promise<boolean> {
  if (typeof source !== 'string') return false;
  const resolved = path.resolve(source);
  if (!resolved.startsWith(path.resolve(attemptDir) + path.sep)) return false;
  try { await copyFile(resolved, destination); return true; } catch { return false; }
}

/** Replays the saved file using standard Playwright, with no model client or credentials. */
export async function verifyReproduction(options: VerifyOptions): Promise<VerificationResult> {
  const attempts = options.attempts ?? 2;
  if (!Number.isSafeInteger(attempts) || attempts < 1 || attempts > 10) throw new Error('Verification attempts must be between 1 and 10');
  const url = new URL(options.baseUrl);
  if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password) throw new Error('Verification requires a credential-free HTTP target');
  const dir = path.resolve(options.dir);
  await readFile(path.join(dir, 'repro.spec.ts'), 'utf8');
  const timeoutMs = options.timeoutMs ?? 120000;
  if (!Number.isFinite(timeoutMs) || timeoutMs <= 0) throw new Error('Verification timeout must be positive');
  const deadline = Date.now() + timeoutMs;
  const outcomes: VerificationAttempt[] = [];
  for (let attempt = 1; attempt <= attempts; attempt++) {
    const remaining = deadline - Date.now();
    if (remaining < 1000 || options.signal?.aborted) {
      outcomes.push({ attempt, classification: 'inconclusive', stage: 'not_started', errorType: options.signal?.aborted ? 'cancelled' : 'verification_timeout', exitCode: null });
      break;
    }
    const nonce = randomUUID();
    const attemptDir = path.join(dir, `verification-attempt-${attempt}-${nonce.slice(0, 8)}`);
    await mkdir(attemptDir, { recursive: true });
    const evidencePath = path.join(attemptDir, 'evidence.json');
    const reportPath = path.join(attemptDir, 'results.json');
    const configPath = path.join(attemptDir, 'playwright.config.mjs');
    const processBudget = Math.floor(remaining / (attempts - attempt + 1));
    const testTimeout = Math.max(1, processBudget - 1500);
    await writeFile(configPath, `export default ${JSON.stringify({
      testDir: dir, testMatch: 'repro.spec.ts', outputDir: path.join(attemptDir, 'test-results'),
      workers: 1, retries: 0, fullyParallel: false, forbidOnly: true, timeout: testTimeout,
      globalTimeout: Math.max(1, processBudget - 500), reporter: [['json', { outputFile: reportPath }]],
      use: { browserName: 'chromium', headless: true },
    }, null, 2)};\n`);
    const execution = await execute(configPath, isolatedEnvironment({
      BASE_URL: url.href, BUGREPLAY_EVIDENCE_PATH: evidencePath, BUGREPLAY_ATTEMPT_NONCE: nonce,
      BUGREPLAY_TEST_TIMEOUT_MS: String(testTimeout),
    }), processBudget, options.signal);
    await writeFile(path.join(dir, `verification-${attempt}-stdout.txt`), execution.stdout);
    await writeFile(path.join(dir, `verification-${attempt}-stderr.txt`), execution.stderr);
    const [report, evidence] = await Promise.all([readJson(reportPath), readJson(evidencePath)]);
    const classification = classify(report, evidence, nonce, execution.exitCode, execution.interrupted);
    const outcome: VerificationAttempt = {
      attempt, ...classification, stage: evidence?.stage ?? 'process_start', exitCode: execution.exitCode,
      ...(validCart(evidence?.initialCart) ? { initialCart: evidence.initialCart } : {}),
      ...(validCart(evidence?.actualCart) ? { actualCart: evidence.actualCart } : {}),
      ...(evidence ? { evidence } : {}),
    };
    if (evidence?.contextClosed === true && await publishFile(evidence.videoPath, attemptDir, path.join(dir, `verification-${attempt}.webm`))) {
      outcome.videoName = `verification-${attempt}.webm`;
    }
    for (const [field, suffix] of [['beforeScreenshot', 'before'], ['afterScreenshot', 'after']] as const) {
      await publishFile(evidence?.[field], attemptDir, path.join(dir, `verification-${attempt}-${suffix}.png`));
    }
    outcomes.push(outcome);
    await writeFile(path.join(dir, `verification-${attempt}.json`), JSON.stringify(outcome, null, 2) + '\n');
  }
  const matchedFailures = outcomes.filter((outcome) => outcome.classification === 'matched_failure').length;
  const allCompleted = outcomes.length === attempts;
  const verdict = allCompleted && attempts >= 2 && matchedFailures === attempts ? 'confirmed' :
    allCompleted && outcomes.every((outcome) => outcome.classification === 'passed') ? 'not_matched' : 'inconclusive';
  const result: VerificationResult = { attempts: outcomes, matchedFailures, verdict };
  await writeFile(path.join(dir, 'verification.json'), JSON.stringify(result, null, 2) + '\n');
  return result;
}

import { randomUUID } from 'node:crypto';
import { mkdir } from 'node:fs/promises';
import { join } from 'node:path';
import { chromium, type Browser as PlaywrightBrowser, type BrowserContext, type Locator, type Page } from 'playwright';
import type { ActionRecord, ActionSemantic, BrowserObservation, CartCheckpoint, CartItem, LocatorSpec, ReproStep, ShopState } from '@bugreplay/contracts';

export interface BrowserEvent {
  type: 'action' | 'observation' | 'tool_error';
  message: string;
  data?: Record<string, unknown>;
  screenshotName?: string;
}
export interface BrowserOptions {
  targetUrl: string;
  allowedOrigins: string[];
  artifactDir: string;
  onEvent?: (event: BrowserEvent) => void | Promise<void>;
  timeoutMs?: number;
  deadlineAt?: number;
}
export interface BrowserAction {
  kind: 'click' | 'fill' | 'select' | 'check';
  ref: string;
  value?: string;
  checked?: boolean;
}
export class BrowserToolError extends Error {
  constructor(message: string) { super(message); this.name = 'BrowserToolError'; }
