  const checkpoint = matching[0];
  validateState(checkpoint.state);
  const captureIndex = episode.findIndex((record) => record.step.id === checkpoint.afterStepId);
  const endIndex = episode.findIndex((record) => record.step.id === candidate.endStepId);
  if (captureIndex < 0 || endIndex <= captureIndex) throw new Error('Candidate end must follow its checkpoint');
