      final.after.saveSeq <= final.before.saveSeq || final.after.address.trim() === checkpoint.state.address.trim() ||
      final.after.address.trim() === final.before.address.trim() || !final.after.address.trim()) {
    throw new Error('Candidate must end with a completed new save of a changed address');
  }
  return reproductionSchema.parse({
    version: 1, complaint: input.complaint, expected: input.expected, observed: candidate.observed,
    steps: episode.slice(0, endIndex + 1).map((record) => record.step),
    oracle: { kind: input.oracleKind, captureAfterStepId: checkpoint.afterStepId, compareAfterStepId: final.step.id },
  });
}

